import argparse
import datetime
import json
import time

import requests


def get_timestamp() -> str:
    """
    Return string with current timestamp.

    :return: String with current timestamp
    """
    ts = time.time()
    return datetime.datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S")


class PositionerCommunication:
    """Communication with positioner."""

    def __init__(self, url: str, http_method: str = "get", timeout: float = 15.5, payload: dict = None):
        """
        Communication with positioner.

        :param url: address to communicate - http://192.168.3.4:2500/api/otaLeft/cmd
        :param http_method: method to send payload: get or put or post
        :param timeout: timeout for communication
        :param payload: dict with data to send ad parameters
        """
        self.ans = None
        self.status_code = None
        self.msg = None
        self.headers = None
        self.full_url: str = url
        self.http_method: str = http_method
        self.timeout: float = timeout
        self.payload: dict = {} if payload is None else payload
        self.headers: dict = {"Content-Type": "application/json"}
        self.validate_input()

    def validate_input(self) -> None:
        """
        Validate parameters set in the object.

        :raise: Exception if parameters don't match.
        """
        if self.http_method not in ["get", "post", "put"]:
            raise Exception(f"Passed http_method as {self.http_method}. Expected 'get' or 'post' or 'put'.")

    def act(self):
        """Execute communication with positioner."""
        self.validate_input()

        requests_method = {"get": requests.get, "put": requests.put, "post": requests.post}
        print(f">url='{self.full_url}',\n>payload='{self.payload}',\n>headers='{self.headers}'")
        start_time = time.monotonic()
        http_communicate = requests_method[self.http_method]
        r: requests.Response = http_communicate(self.full_url, headers=self.headers, data=self.payload, timeout=self.timeout)
        end_time = time.monotonic()
        print(f"Communication time: '{end_time - start_time}' seconds.")
        code: int = r.status_code
        if code == 200:
            self.ans = r.json()
        self.status_code = code
        self.msg = r.text
        self.headers = r.headers


class PositionerCommunicationConsole:
    """Console wrapper to communication."""

    def __init__(self):
        """Init the object."""
        self.http_method = None
        self.url = None
        self.timeout = None
        self.payload = None

        self.ans_str = None
        self.ans_dict = None
        self.status_code = None
        self.msg = None
        self.headers = None

    def parse_arguments(self) -> None:
        """Parse passed arguments."""
        parser = argparse.ArgumentParser(description="Send request to positioner and print answer.")
        parser.add_argument("-hm", "--http_method", default="get", help="HTTP method.", choices=["get", "put", "post"])
        parser.add_argument("-a", "--address", help="Address (URL) to send request", required=True)
        parser.add_argument("-t", "--timeout", help="Timeout", type=float, default=94.0)
        parser.add_argument("-p", "--payload", help="String with payload", default=None)

        args = parser.parse_args()

        self.http_method = args.http_method
        self.url = args.address
        self.timeout = args.timeout
        self.payload = args.payload

    def run(self) -> None:
        """Run communication."""
        self.parse_arguments()
        pc = PositionerCommunication(url=self.url, timeout=self.timeout, payload=self.payload, http_method=self.http_method)
        pc.act()
        self.ans_dict = pc.ans
        if pc.ans is None:
            self.ans_str = ""
        else:
            self.ans_str = json.dumps(pc.ans, sort_keys=True)
        self.status_code = pc.status_code
        self.msg = pc.msg
        self.headers = pc.headers


def main() -> None:
    """Start function."""
    print(f"Started at {get_timestamp()}")
    pc = PositionerCommunicationConsole()
    pc.run()
    print(f"\n\n<code: '{pc.status_code}'")
    print(f"<json: '{pc.ans_str}'")
    print(f"<text: '{pc.msg}'")
    print(f"<headers: '{pc.headers}'")
    print(f"\nFinished at {get_timestamp()}")


if __name__ == "__main__":
    main()
